changeSet.sql:
create table "${schema}".demo_manager ( id bigint generated always as identity primary key, code varchar(64) not null unique, full_name varchar(256) not null );
create table "${schema}".demo_client ( id bigint generated always as identity primary key, inn varchar(12) not null unique, name varchar(512) not null, industry varchar(32) not null check (industry in ('CONSTRUCTION', 'PROFESSIONAL', 'MANUFACTURING', 'TRADE')), okved_section varchar(2), region varchar(256), abs_liquidity numeric(19, 6), ar_turnover_days integer, is_core boolean not null default false, manager_code varchar(64) not null, edo_consent boolean not null default true, factoring_client boolean not null default false, control_case varchar(16) ); comment on table "${schema}".demo_client is 'Клиенты банка (поставщики), синтетика генератора'; comment on column "${schema}".demo_client.abs_liquidity is 'Абсолютная ликвидность: признак TR (п. 5.3) и кассовый разрыв (Р-15)'; comment on column "${schema}".demo_client.factoring_client is 'Уже клиент факторинга: не загружается (сноска к п. 1.1)';
create table "${schema}".demo_buyer ( id bigint generated always as identity primary key, inn varchar(12) not null unique, ogrn varchar(15), name varchar(512) not null, okved varchar(16), okved_section varchar(2), region varchar(256), registration_date date, data_date date ); comment on table "${schema}".demo_buyer is 'Реестр покупателей (реальные компании). ИНН из УПД вне реестра - нет данных по покупателю (п. 1.4)';

create table "${schema}".demo_contract ( id bigint generated always as identity primary key, client_inn varchar(12) not null, buyer_inn varchar(12) not null, number varchar(64) not null, contract_date date not null, deferral_days integer not null check (deferral_days >= 0), constraint ux_demo_contract unique (client_inn, number) );
create table "${schema}".demo_upd ( id bigint generated always as identity primary key, client_inn varchar(12) not null, buyer_inn varchar(12) not null, contract_number varchar(64) not null, number varchar(64) not null, upd_date date not null, amount numeric(19, 2) not null check (amount > 0), control_case varchar(16), constraint ux_demo_upd unique (number, upd_date, client_inn) ); comment on column "${schema}".demo_upd.upd_date is 'Дата отгрузки, она же дата подписания';
create table "${schema}".demo_payment ( id bigint generated always as identity primary key, source_id varchar(64) not null unique, client_inn varchar(12) not null, payer_inn varchar(12) not null, amount numeric(19, 2) not null check (amount > 0), payment_date date not null, purpose varchar(1024), control_case varchar(16) ); comment on table "${schema}".demo_payment is 'Поступления из выписок клиентов (п. 1.2)';

create table "${schema}".demo_egrul_status ( inn varchar(12) primary key, ogrn varchar(15), name varchar(512), region varchar(256), debtor_category varchar(128), status varchar(512), status_date date );
create table "${schema}".demo_bankruptcy_case ( id bigint generated always as identity primary key, inn varchar(12) not null, case_number varchar(64) not null, court varchar(512), applicant varchar(64), stage varchar(128), start_date date, start_date_source varchar(128), observation_from date, rehabilitation_from date, external_management_from date, declared_bankrupt_on date, receivership_from date, end_date date, outcome varchar(512), first_intent_date date, constraint ux_demo_bankruptcy_case unique (inn, case_number) );
create table "${schema}".demo_efrsb_event ( id bigint generated always as identity primary key, inn varchar(12) not null, case_number varchar(64), event_type varchar(128), event varchar(1024), details text, event_date date, published_on date, message_number varchar(32) not null unique, annulled boolean not null default false, url varchar(512) ); create index ix_demo_efrsb_event_inn on "${schema}".demo_efrsb_event (inn);

alter table "${schema}".demo_efrsb_event drop constraint demo_efrsb_event_message_number_key;
create unique index ux_demo_efrsb_event on "${schema}".demo_efrsb_event
    (inn, coalesce(case_number, ''), message_number, coalesce(event_type, ''), coalesce(event, ''));

create table "${schema}".demo_factoring_package
(
    id          bigint generated always as identity primary key,
    offer_id    bigint      not null unique,
    payload     jsonb       not null,
    received_at timestamptz not null default now()
);
comment on table "${schema}".demo_factoring_package is 'Имитация ВТБ Факторинга: принятые пакеты (п. 6.2)';

create table "${schema}".demo_risk_signal
(
    id          bigint generated always as identity primary key,
    run_id      bigint      not null,
    buyer_inn   varchar(12) not null,
    upd_ids     jsonb       not null,
    payload     jsonb,
    received_at timestamptz not null default now(),
    constraint ux_demo_risk_signal unique (run_id, buyer_inn)
);
comment on table "${schema}".demo_risk_signal is 'Имитация риск-подразделения: сигнал о проблемном покупателе (п. 3.10 в)';

create table "${schema}".manager ( id bigint generated always as identity primary key, code varchar(64) not null unique, full_name varchar(256) not null );
create table "${schema}".client ( id bigint generated always as identity primary key, inn varchar(12) not null unique, name varchar(512) not null, industry varchar(32) not null check (industry in ('CONSTRUCTION', 'PROFESSIONAL', 'MANUFACTURING', 'TRADE')), okved_section varchar(2), region varchar(256), abs_liquidity numeric(19, 6), ar_turnover_days integer, is_core boolean not null default false, manager_id bigint not null references "${schema}".manager (id), edo_consent boolean not null, factoring_client boolean not null, loaded_at timestamptz not null default now() ); create index ix_client_manager on "${schema}".client (manager_id);
create table "${schema}".buyer ( id bigint generated always as identity primary key, inn varchar(12) not null unique, ogrn varchar(15), name varchar(512) not null, okved varchar(16), okved_section varchar(2), region varchar(256), registration_date date, loaded_at timestamptz not null default now() );

create table "${schema}".run ( id bigint generated always as identity primary key, status varchar(32) not null check (status in ('RUNNING', 'DONE', 'DONE_WITH_WARNINGS', 'STOPPED')), calc_date date not null, client_ids jsonb, initiator_type varchar(32) not null check (initiator_type in ('OPERATOR', 'API')), initiator varchar(256), started_at timestamptz not null default now(), finished_at timestamptz, data_date date, snapshot_date date, parameters jsonb not null, model_versions jsonb, summary jsonb, error_message text ); comment on column "${schema}".run.client_ids is 'Набор клиентов прогона (ПР-2); null - все клиенты'; comment on column "${schema}".run.parameters is 'Снимок таблицы parameter на момент запуска (Р-9, НФР-5)';
-- ПР-3: одновременно выполняется не более одного прогона create unique index ux_run_single_running on "${schema}".run ((true)) where status = 'RUNNING'; create index ix_run_started_at on "${schema}".run (started_at desc);
create table "${schema}".run_step ( run_id bigint not null references "${schema}".run (id), step_no smallint not null check (step_no between 1 and 5), status varchar(32) not null check (status in ('PENDING', 'RUNNING', 'DONE', 'WARNING', 'STOPPED')), started_at timestamptz, finished_at timestamptz, metrics jsonb, primary key (run_id, step_no) );

create table "${schema}".contract ( id bigint generated always as identity primary key, client_id bigint not null references "${schema}".client (id), buyer_id bigint references "${schema}".buyer (id), buyer_inn varchar(12) not null, number varchar(64) not null, contract_date date not null, deferral_days integer not null check (deferral_days >= 0), constraint ux_contract unique (client_id, number) );
create table "${schema}".upd ( id bigint generated always as identity primary key, client_id bigint not null references "${schema}".client (id), buyer_id bigint references "${schema}".buyer (id), buyer_inn varchar(12) not null, contract_id bigint references "${schema}".contract (id), number varchar(64) not null, upd_date date not null, amount numeric(19, 2) not null check (amount > 0), first_loaded_run_id bigint references "${schema}".run (id), -- НФР-3: повторная загрузка того же УПД не создаёт дубль constraint ux_upd unique (number, upd_date, client_id) ); comment on column "${schema}".upd.buyer_id is 'null - покупателя нет в реестре: нет данных по покупателю (п. 1.4)'; create index ix_upd_buyer on "${schema}".upd (buyer_inn); create index ix_upd_contract on "${schema}".upd (contract_id);
create table "${schema}".payment ( id bigint generated always as identity primary key, source_id varchar(64) not null unique, client_id bigint not null references "${schema}".client (id), payer_inn varchar(12) not null, amount numeric(19, 2) not null check (amount > 0), payment_date date not null, purpose varchar(1024), first_loaded_run_id bigint references "${schema}".run (id) ); create index ix_payment_client_payer on "${schema}".payment (client_id, payer_inn);

create table "${schema}".buyer_score ( run_id bigint not null references "${schema}".run (id), buyer_id bigint not null references "${schema}".buyer (id), has_external_data boolean not null, stop_factor varchar(16) check (stop_factor in ('BANKRUPTCY', 'LIQUIDATION', 'EXCLUSION')), has_payment_history boolean not null, pd numeric(9, 6), pd_source varchar(8) check (pd_source in ('MODEL', 'BASE')), low_data boolean not null default false, risk_level char(1) check (risk_level in ('A', 'B', 'C', 'D')), reasons jsonb, model_version varchar(64), data_date date, from_cache boolean not null default false, primary key (run_id, buyer_id) );
create table "${schema}".buyer_pd_cache ( buyer_id bigint not null references "${schema}".buyer (id), data_date date not null, model_version varchar(64) not null, pd numeric(9, 6) not null, pd_source varchar(8) not null check (pd_source in ('MODEL', 'BASE')), low_data boolean not null, reasons jsonb, calculated_at timestamptz not null default now(), primary key (buyer_id, data_date, model_version) ); comment on table "${schema}".buyer_pd_cache is 'PD не пересчитывается, пока не обновились данные покупателя или версия модели (п. 4.2)';
create table "${schema}".upd_score ( run_id bigint not null references "${schema}".run (id), upd_id bigint not null references "${schema}".upd (id), status varchar(32) not null check (status in ('SCORED', 'NO_PAYMENT_HISTORY', 'ERROR')), delay_threshold_days smallint, p_delay numeric(9, 6), p_overdue_90 numeric(9, 6), expected_delay_days numeric(9, 2), no_pair_history boolean not null default false, model_version varchar(64), attempts smallint not null default 1, error_message text, primary key (run_id, upd_id) );

create table "${schema}".offer ( id bigint generated always as identity primary key, upd_id bigint not null references "${schema}".upd (id), client_id bigint not null references "${schema}".client (id), buyer_id bigint not null references "${schema}".buyer (id), manager_id bigint not null references "${schema}".manager (id), status varchar(16) not null check (status in ('QUEUED', 'TRANSFERRED', 'REJECTED', 'REVOKED')), revoke_reason varchar(32) check (revoke_reason in ('UPD_PAID', 'UPD_OVERDUE', 'NO_LONGER_ELIGIBLE')), created_run_id bigint not null references "${schema}".run (id), last_run_id bigint not null references "${schema}".run (id), queued_at timestamptz not null default now(), is_new boolean not null default true, ead numeric(19, 2) not null, price numeric(19, 2) not null, price_rate numeric(9, 6) not null, term_days integer not null, income numeric(19, 2) not null, el numeric(19, 2) not null, risk_level char(1) not null, pd numeric(9, 6) not null, rank_value numeric(19, 2) not null, flags jsonb not null default '{}', reasons jsonb, reasons_text text, message_draft text, decided_by varchar(256), decided_at timestamptz, updated_at timestamptz not null default now(), check ((status = 'REVOKED') = (revoke_reason is not null)), check ((status in ('TRANSFERRED', 'REJECTED')) = (decided_at is not null)) ); comment on table "${schema}".offer is 'Предложение по УПД; живёт между прогонами (ПР-8), решение менеджера - блок 6';
-- ПР-8, п. 6.4: по УПД не больше одного предложения в очереди, после решения новых не формируется create unique index ux_offer_upd_active on "${schema}".offer (upd_id) where status in ('QUEUED', 'TRANSFERRED', 'REJECTED'); create index ix_offer_manager_status on "${schema}".offer (manager_id, status); create index ix_offer_buyer_status on "${schema}".offer (buyer_id, status);
create table "${schema}".notification ( id bigint generated always as identity primary key, run_id bigint not null references "${schema}".run (id), manager_id bigint not null references "${schema}".manager (id), type varchar(16) not null check (type in ('NEW_OFFER', 'OVERDUE', 'REMINDER', 'RISK_SIGNAL')), client_id bigint, buyer_id bigint, upd_id bigint, offer_id bigint, payload jsonb, created_at timestamptz not null default now() ); create index ix_notification_manager on "${schema}".notification (manager_id, created_at desc);

alter table "${schema}".demo_client alter column control_case type varchar(128);
alter table "${schema}".demo_upd alter column control_case type varchar(128);
alter table "${schema}".demo_payment alter column control_case type varchar(128);

alter table "${schema}".demo_import_batch drop constraint demo_import_batch_kind_check;
alter table "${schema}".demo_import_batch add constraint demo_import_batch_kind_check
    check (kind in ('GENERATOR', 'EFRSB', 'DELIVERY'));
alter table "${schema}".demo_buyer add column pd numeric(9, 6);
alter table "${schema}".demo_buyer add column pd_model_version varchar(64);
comment on column "${schema}".demo_buyer.pd is 'Готовый PD из партии ML-команды: кэш PD версии pd_model_version (Р-54)';
